# We enforce min_delta >= 6 to avoid trivial cases.
def min_delta(n):
    target = n + 1
    # M runs from 1-n to n+1 in steps of 2
    start = 1 - n
    end = n + 1
    best = None
    for m in range(start, end + 1, 2):
        d = abs(m*m - target)
        if best is None or d < best:
            best = d
    return best
