# Since we can choose any sequence (p_i) with p_0 = 1 and p_i in {±1},
# M ranges over {1 - n, 3 - n, ..., n + 1}. Hence the minimal |S_n| equals
# (a/2) * min_{M in that set} |M^2 - (n+1)|.
if not isinstance(assign, dict):
    # invalid assignment type
    return (False, None)
if 'a' not in assign or 'n' not in assign:
