    return (False, None)
target = n + 1
start = 1 - n
end = n + 1
if (end - start) % 2 != 0:
    # parity step check; range must be compatible with step 2
    return (False, None)
best = None
for m in range(start, end + 1, 2):
    d = abs(m*m - target)
    if best is None or d < best:
        best = d
if best is None:
    # should not happen
    return (False, None)
# Difficulty enforcement: avoid trivial minima
# Minimum zero occurs when target is a perfect square achievable by M parity; disallow
if best == 0:
    return (False, None)
# Also avoid too small cases that can be guessed without structure
if best < 6:
    return (False, None)
# The minimal absolute value equals a * (best/2). best is even because m^2 and target share parity.
answer = a * (best // 2)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

